const html = $node["Adicionar UTM Campaign"].json.html;
const preheader = $node["Adicionar UTM Campaign"].json.preheader;
const utmCampaign = $node["Adicionar UTM Campaign"].json.utm_campaign;

if (!html) {
  throw new Error("HTML não encontrado no node Adicionar UTM Campaign.");
}

if (!preheader) {
  throw new Error("Preheader não encontrado no node Adicionar UTM Campaign.");
}

if (!utmCampaign) {
  throw new Error("utm_campaign não encontrada no node Adicionar UTM Campaign.");
}

return [
  {
    json: {
      preheader,
      utm_campaign: utmCampaign,
      body_base64: Buffer.from(html, "utf8").toString("base64")
    }
  }
];

const ids = items
  .map(item => item.json.id)
  .filter(id => id !== undefined && id !== null)
  .map(id => String(id));

if (ids.length === 0) {
  throw new Error("Nenhuma lista encontrada para criar a campanha.");
}

if (ids.length > 10) {
  throw new Error(`A SendPulse permite no máximo 10 listas por campanha. Foram encontradas ${ids.length}.`);
}

return [
  {
    json: {
      list_ids: ids
    }
  }
];

const html = $node["Baixar HTML"].json.html;
const utmCampaign = $node["Pegar próxima campanha da fila"].json.campanha.utm_campaign;
const preheader = $node["Pegar próxima campanha da fila"].json.campanha.preheader;

if (!html) {
  throw new Error("HTML não encontrado no node Baixar HTML.");
}

if (!utmCampaign) {
  throw new Error("utm_campaign não encontrada no node Interpretar mensagem.");
}

if (!preheader) {
  throw new Error("preheader não encontrado no node Interpretar mensagem.");
}

// Evita quebrar o HTML caso venha algum caractere especial no preheader
function escapeHtml(texto) {
  return String(texto)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

// Bloco oculto usado como preview text/preheader nos clientes de e-mail
const blocoPreheader = `<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:transparent;mso-hide:all;font-size:1px;line-height:1px;">${escapeHtml(preheader)}</div>`;

// Insere o preheader logo após a abertura do <body>
let htmlProcessado;

if (/<body[^>]*>/i.test(html)) {
  htmlProcessado = html.replace(/<body[^>]*>/i, match => `${match}\n${blocoPreheader}`);
} else {
  // Caso raro: se não encontrar <body>, coloca no começo do HTML
  htmlProcessado = `${blocoPreheader}\n${html}`;
}

const linksAntes = [];
const linksDepois = [];

function adicionarUtmCampaign(url) {
  linksAntes.push(url);

  // Ignora links especiais
  if (
    url.startsWith("#") ||
    url.startsWith("mailto:") ||
    url.startsWith("tel:") ||
    url.startsWith("javascript:")
  ) {
    return url;
  }

  // Só mexe em links do site da xxxxxxx
  if (
    !url.startsWith("https://xxxxxxx.com.br") &&
    !url.startsWith("http://xxxxxxx.com.br")
  ) {
    return url;
  }

  const utmCodificada = encodeURIComponent(utmCampaign);

  // Se já tiver utm_campaign, substitui
  if (url.includes("utm_campaign=")) {
    return url.replace(/utm_campaign=[^&"']*/g, "utm_campaign=" + utmCodificada);
  }

  // Se já tiver parâmetros, adiciona com &
  if (url.includes("?")) {
    return url + "&utm_campaign=" + utmCodificada;
  }

  // Se não tiver parâmetros, adiciona com ?
  return url + "?utm_campaign=" + utmCodificada;
}

const htmlComUtm = htmlProcessado.replace(/href=["']([^"']+)["']/gi, (match, url) => {
  const novaUrl = adicionarUtmCampaign(url);
  return match.replace(url, novaUrl);
});

const regexLinks = /href=["']([^"']+)["']/gi;
let match;

while ((match = regexLinks.exec(htmlComUtm)) !== null) {
  linksDepois.push(match[1]);
}

return [
  {
    json: {
      preheader,
      utm_campaign: utmCampaign,
      total_links_encontrados: linksAntes.length,
      primeiros_links_antes: linksAntes.slice(0, 10),
      primeiros_links_depois: linksDepois.slice(0, 10),
      html: htmlComUtm
    }
  }
];

const texto = $json.message?.text?.trim();

const chatIdPermitido = "SEU_CHAT_ID_TELEGRAM";
const chatIdRecebido = String($json.message?.chat?.id);

if (chatIdRecebido !== chatIdPermitido) {
  throw new Error("Usuário não autorizado.");
}

if (!texto) {
  throw new Error("Nenhuma mensagem de texto recebida pelo Telegram.");
}

// Comando /campanha
if (texto === "/campanha") {
  return [
    {
      json: {
        tipo: "instrucao",
        chat_id: chatIdRecebido,
        mensagem: `Envie os dados da campanha em JSON, por exemplo:

{
  "nome_remetente": "xxxxxxx xxxxxxx",
  "email_remetente": "xxxxxxx@xxxxxxx.com.br",
  "nome_campanha": "Campanha Kit Bebidas Maio 2026",
  "assunto": "🥂 Brinde Com Estilo Usando Nosso Kit Bebida Personalizado",
  "preheader": "Identidade • Embalagem • Design",
  "data_envio": "2026-05-16 07:33:00",
  "url_html": "https://xxxxxxx.com.br/news/7367",
  "utm_campaign": "kit_bebidas_personalizados_maio_2026"
}

Comandos disponíveis:
/campanha - ver modelo para criar campanha
/analisar - analisar campanhas já enviadas`
      }
    }
  ];
}

// Comando /analisar
if (texto === "/analisar") {
  return [
    {
      json: {
        tipo: "analise",
        chat_id: chatIdRecebido,
        mensagem: "Modo análise acionado. Próximo passo: buscar campanhas já rodadas no SendPulse."
      }
    }
  ];
}

// Caso não seja comando, tenta interpretar como JSON de campanha
let dados;

try {
  dados = JSON.parse(texto);
} catch (error) {
  throw new Error("A mensagem não está em JSON válido. Envie /campanha para ver o modelo.");
}

const camposObrigatorios = [
  "nome_remetente",
  "email_remetente",
  "nome_campanha",
  "assunto",
  "preheader",
  "data_envio",
  "url_html",
  "utm_campaign"
];

const faltando = camposObrigatorios.filter(campo => !dados[campo]);

if (faltando.length > 0) {
  throw new Error("Campos obrigatórios ausentes: " + faltando.join(", "));
}

return [
  {
    json: {
      tipo: "campanha",
      chat_id: chatIdRecebido,
      campanha: dados
    }
  }
];

