const campanhas = items.map(item => item.json);

const ultimas60 = campanhas
  .sort((a, b) => new Date(b.send_date) - new Date(a.send_date))
  .slice(0, 60);

if (ultimas60.length === 0) {
  return [
    {
      json: {
        chat_id: $node["Interpretar mensagem"].json["chat_id"],
        dados_campanhas: "Nenhuma campanha encontrada no SendPulse."
      }
    }
  ];
}

const campanhasFormatadas = ultimas60.map((campanha, index) => {
  return {
    posicao: index + 1,
    id: campanha.id ?? null,
    nome: campanha.name ?? null,
    status: campanha.status ?? null,
    data_envio: campanha.send_date ?? null,
    quantidade_emails: campanha.all_email_qty ?? campanha.tariff_email_qty ?? 0,
    emails_tarifados: campanha.tariff_email_qty ?? 0,
    emails_pagos: campanha.paid_email_qty ?? 0,
    moeda: campanha.overdraft_currency ?? null,
    remetente_nome: campanha.message?.sender_name ?? null,
    remetente_email: campanha.message?.sender_email ?? null,
    assunto: campanha.message?.subject ?? null,
    lista_id: campanha.message?.list_id ?? null,
    statistics: campanha.statistics ?? null
  };
});

return [
  {
    json: {
      chat_id: $node["Interpretar mensagem"].json["chat_id"],
      total_campanhas_analisadas: campanhasFormatadas.length,
      campanhas: campanhasFormatadas
    }
  }
];

const respostaIA = $node["Analisar campanhas com IA"].json.output[0].content[0].text;
const chatId = $node["Interpretar mensagem"].json.chat_id;

if (!respostaIA) {
  throw new Error("Resposta da IA não encontrada.");
}

let campanhas;

try {
  campanhas = JSON.parse(respostaIA);
} catch (error) {
  throw new Error("A resposta da IA não é um JSON válido. Verifique se o prompt está retornando apenas o array JSON.");
}

if (!Array.isArray(campanhas)) {
  throw new Error("A resposta da IA precisa ser um array JSON.");
}

if (campanhas.length !== 9) {
  throw new Error(`A IA retornou ${campanhas.length} campanhas. O esperado são exatamente 9.`);
}

return campanhas.map((campanha, index) => {
  const mensagem = JSON.stringify(campanha, null, 2);

  return {
    json: {
      chat_id: chatId,
      numero_campanha: index + 1,
      campanha,
      mensagem
    }
  };
});

const campanha = $node["Interpretar mensagem"].json.campanha;
const chatId = $node["Interpretar mensagem"].json.chat_id;

if (!campanha) {
  throw new Error("Campanha não encontrada no node Interpretar mensagem.");
}

const camposObrigatorios = [
  "nome_remetente",
  "email_remetente",
  "nome_campanha",
  "assunto",
  "preheader",
  "data_envio",
  "url_html",
  "utm_campaign"
];

const faltando = camposObrigatorios.filter(campo => !campanha[campo]);

if (faltando.length > 0) {
  throw new Error("Campos obrigatórios ausentes: " + faltando.join(", "));
}

const agora = new Date();

const idFila = `fila_${Date.now()}_${campanha.utm_campaign}`;

return [
  {
    json: {
      key: idFila,
      status: "pendente",
      criado_em: agora.toISOString(),
      tentativas: 0,
      chat_id: chatId,
      campanha
    }
  }
];

const itemFila = $json;

if (!itemFila.key) {
  throw new Error("Key da fila não encontrada.");
}

if (!itemFila.campanha) {
  throw new Error("Campanha não encontrada no item da fila.");
}

const staticData = $getWorkflowStaticData("global");

if (!staticData.fila_campanhas) {
  staticData.fila_campanhas = [];
}

// Evita duplicar a mesma key se o node for executado de novo
const jaExiste = staticData.fila_campanhas.some(item => item.key === itemFila.key);

if (jaExiste) {
  return [
    {
      json: {
        ...itemFila,
        salvo_na_fila: false,
        mensagem: `Esta campanha já estava na fila.

Nome: ${itemFila.campanha.nome_campanha}
Status: ${itemFila.status}`
      }
    }
  ];
}

staticData.fila_campanhas.push({
  key: itemFila.key,
  status: itemFila.status || "pendente",
  criado_em: itemFila.criado_em,
  tentativas: itemFila.tentativas || 0,
  chat_id: itemFila.chat_id,
  campanha: itemFila.campanha,
  sendpulse_id: null,
  erro: null
});

const posicao = staticData.fila_campanhas.filter(item => item.status === "pendente").length;

return [
  {
    json: {
      ...itemFila,
      salvo_na_fila: true,
      posicao_fila: posicao,
      mensagem: `Campanha adicionada à fila.

Nome: ${itemFila.campanha.nome_campanha}
Assunto: ${itemFila.campanha.assunto}
Data de envio: ${itemFila.campanha.data_envio}
Status: pendente
Posição na fila: ${posicao}`
    }
  }
];

const staticData = $getWorkflowStaticData("global");

if (!staticData.fila_campanhas) {
  staticData.fila_campanhas = [];
}

const fila = staticData.fila_campanhas;

const proxima = fila.find(item => item.status === "pendente");

if (!proxima) {
  return [];
}

proxima.status = "processando";
proxima.processando_em = new Date().toISOString();
proxima.tentativas = (proxima.tentativas || 0) + 1;

return [
  {
    json: {
      ...proxima,
      campanha: proxima.campanha,
      chat_id: proxima.chat_id,
      key: proxima.key
    }
  }
];
